-- Initial Jobs Territory relational schema.
CREATE TABLE `users` (`id` VARCHAR(191) NOT NULL, `email` VARCHAR(191) NOT NULL, `password_hash` VARCHAR(191) NOT NULL, `role` ENUM('CANDIDATE', 'COMPANY', 'ADMIN') NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, UNIQUE INDEX `users_email_key`(`email`), INDEX `users_role_idx`(`role`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `candidate_profiles` (`id` VARCHAR(191) NOT NULL, `user_id` VARCHAR(191) NOT NULL, `full_name` VARCHAR(191) NULL, `phone` VARCHAR(191) NULL, `headline` VARCHAR(191) NULL, `bio` TEXT NULL, `location` VARCHAR(191) NULL, `profile_photo_key` VARCHAR(191) NULL, `resume_key` VARCHAR(191) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, UNIQUE INDEX `candidate_profiles_user_id_key`(`user_id`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `companies` (`id` VARCHAR(191) NOT NULL, `owner_id` VARCHAR(191) NOT NULL, `name` VARCHAR(191) NOT NULL, `slug` VARCHAR(191) NOT NULL, `description` TEXT NULL, `website` VARCHAR(191) NULL, `contact_email` VARCHAR(191) NOT NULL, `status` ENUM('PENDING', 'APPROVED', 'REJECTED', 'SUSPENDED') NOT NULL DEFAULT 'PENDING', `rejection_reason` TEXT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, UNIQUE INDEX `companies_owner_id_key`(`owner_id`), UNIQUE INDEX `companies_slug_key`(`slug`), INDEX `companies_status_idx`(`status`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `verification_documents` (`id` VARCHAR(191) NOT NULL, `company_id` VARCHAR(191) NOT NULL, `type` ENUM('REGISTRATION_CERTIFICATE', 'TAX_DOCUMENT', 'IDENTITY_DOCUMENT', 'OTHER') NOT NULL, `storage_key` VARCHAR(191) NOT NULL, `original_name` VARCHAR(191) NOT NULL, `mime_type` VARCHAR(191) NOT NULL, `status` ENUM('PENDING', 'ACCEPTED', 'REJECTED') NOT NULL DEFAULT 'PENDING', `rejection_reason` TEXT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, INDEX `verification_documents_company_id_status_idx`(`company_id`, `status`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `jobs` (`id` VARCHAR(191) NOT NULL, `company_id` VARCHAR(191) NOT NULL, `title` VARCHAR(191) NOT NULL, `description` TEXT NOT NULL, `location` VARCHAR(191) NULL, `employment_type` VARCHAR(191) NULL, `salary_min` DECIMAL(12, 2) NULL, `salary_max` DECIMAL(12, 2) NULL, `status` ENUM('DRAFT', 'PUBLISHED', 'CLOSED', 'SUSPENDED') NOT NULL DEFAULT 'DRAFT', `published_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, INDEX `jobs_status_published_at_idx`(`status`, `published_at`), INDEX `jobs_company_id_status_idx`(`company_id`, `status`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `applications` (`id` VARCHAR(191) NOT NULL, `job_id` VARCHAR(191) NOT NULL, `candidate_id` VARCHAR(191) NOT NULL, `cover_note` TEXT NULL, `status` ENUM('SUBMITTED', 'UNDER_REVIEW', 'SHORTLISTED', 'REJECTED', 'HIRED', 'WITHDRAWN') NOT NULL DEFAULT 'SUBMITTED', `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, INDEX `applications_candidate_id_status_idx`(`candidate_id`, `status`), UNIQUE INDEX `applications_job_id_candidate_id_key`(`job_id`, `candidate_id`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `admin_review_records` (`id` VARCHAR(191) NOT NULL, `admin_id` VARCHAR(191) NOT NULL, `company_id` VARCHAR(191) NOT NULL, `decision` ENUM('APPROVED', 'REJECTED', 'SUSPENDED') NOT NULL, `reason` TEXT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `admin_review_records_company_id_created_at_idx`(`company_id`, `created_at`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `candidate_profiles` ADD CONSTRAINT `candidate_profiles_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `companies` ADD CONSTRAINT `companies_owner_id_fkey` FOREIGN KEY (`owner_id`) REFERENCES `users`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `verification_documents` ADD CONSTRAINT `verification_documents_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `companies`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `jobs` ADD CONSTRAINT `jobs_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `companies`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `applications` ADD CONSTRAINT `applications_job_id_fkey` FOREIGN KEY (`job_id`) REFERENCES `jobs`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `applications` ADD CONSTRAINT `applications_candidate_id_fkey` FOREIGN KEY (`candidate_id`) REFERENCES `users`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `admin_review_records` ADD CONSTRAINT `admin_review_records_admin_id_fkey` FOREIGN KEY (`admin_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `admin_review_records` ADD CONSTRAINT `admin_review_records_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `companies`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
